using System;
namespace ZiXing {
 public sealed class Mask {
  public readonly int Width,Height;public readonly byte[] Pixels;
  public Mask(int w,int h,byte[] pixels){if(w<1||h<1||pixels.Length!=checked(w*h))throw new ArgumentException("Invalid mask");Width=w;Height=h;Pixels=pixels;}
  public int[] Tight(){int l=Width,r=-1,t=Height,b=-1;for(int y=0;y<Height;y++)for(int x=0;x<Width;x++)if(Pixels[y*Width+x]<170){l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);b=Math.Max(b,y);}return r<l?null:new[]{l,t,r-l+1,b-t+1};}
  public Mask Normalize(int[] rect,int w,int h){var dst=new byte[checked(w*h)];var x0=new int[w];var x1=new int[w];for(int x=0;x<w;x++){x0[x]=Math.Max(0,Math.Min(Width-1,(int)(rect[0]+(x+.25)*rect[2]/w)));x1[x]=Math.Max(0,Math.Min(Width-1,(int)(rect[0]+(x+.75)*rect[2]/w)));}for(int y=0;y<h;y++){int y0=Math.Max(0,Math.Min(Height-1,(int)(rect[1]+(y+.25)*rect[3]/h)))*Width,y1=Math.Max(0,Math.Min(Height-1,(int)(rect[1]+(y+.75)*rect[3]/h)))*Width;for(int x=0;x<w;x++)dst[y*w+x]=(byte)((Pixels[y0+x0[x]]+Pixels[y0+x1[x]]+Pixels[y1+x0[x]]+Pixels[y1+x1[x]])/4);}return new Mask(w,h,dst);}
  public Mask[] SplitIdeographs(int count){if(count<2||count>40||Width<count*4)return null;var ink=new int[Width];for(int x=0;x<Width;x++)for(int y=0;y<Height;y++)if(Pixels[y*Width+x]<170)ink[x]++;var cuts=new int[count+1];cuts[count]=Width;double cell=Width/(double)count;for(int i=1;i<count;i++){double predicted=i*cell,best=double.MaxValue;int cut=-1;for(int x=Math.Max(cuts[i-1]+2,(int)(predicted-cell*.27));x<Math.Min(Width-1,predicted+cell*.27);x++){double value=ink[x]+ink[x-1]+Math.Abs(x-predicted)*.035;if(value<best){best=value;cut=x;}}if(cut<0||ink[cut]+ink[cut-1]>Height*.24)return null;cuts[i]=cut;}var result=new Mask[count];for(int i=0;i<count;i++){int l=cuts[i],r=cuts[i+1]-1,t=Height,b=-1;for(int y=0;y<Height;y++)for(int x=l;x<=r;x++)if(Pixels[y*Width+x]<170){t=Math.Min(t,y);b=Math.Max(b,y);}if(b<t)return null;int il=r,ir=l;for(int x=l;x<=r;x++)for(int y=t;y<=b;y++)if(Pixels[y*Width+x]<170){il=Math.Min(il,x);ir=Math.Max(ir,x);}result[i]=Normalize(new[]{il,t,ir-il+1,b-t+1},32,48);}return result;}
  float[] Distances(){var d=new float[Pixels.Length];for(int i=0;i<d.Length;i++)d[i]=Pixels[i]<170?0:1000;for(int y=0;y<Height;y++)for(int x=0;x<Width;x++){int i=y*Width+x;if(x>0)d[i]=Math.Min(d[i],d[i-1]+1);if(y>0){d[i]=Math.Min(d[i],d[i-Width]+1);if(x>0)d[i]=Math.Min(d[i],d[i-Width-1]+1.414f);if(x+1<Width)d[i]=Math.Min(d[i],d[i-Width+1]+1.414f);}}for(int y=Height-1;y>=0;y--)for(int x=Width-1;x>=0;x--){int i=y*Width+x;if(x+1<Width)d[i]=Math.Min(d[i],d[i+1]+1);if(y+1<Height){d[i]=Math.Min(d[i],d[i+Width]+1);if(x>0)d[i]=Math.Min(d[i],d[i+Width-1]+1.414f);if(x+1<Width)d[i]=Math.Min(d[i],d[i+Width+1]+1.414f);}}return d;}
  public static double ShapeSimilarity(Mask a,Mask b){double overlap=Similarity(a,b);var da=a.Distances();var db=b.Distances();double nearA=0,nearB=0,areaA=0,areaB=0;for(int i=0;i<a.Pixels.Length;i++){double av=(255-a.Pixels[i])/255.0,bv=(255-b.Pixels[i])/255.0;areaA+=av;areaB+=bv;nearA+=av*Math.Max(0,1-db[i]/3);nearB+=bv*Math.Max(0,1-da[i]/3);}if(areaA==0||areaB==0)return 0;double density=Math.Sqrt(Math.Min(areaA,areaB)/Math.Max(areaA,areaB));return .8*overlap+.2*.5*(nearA/areaA+nearB/areaB)*density;}
  public static double Similarity(Mask a,Mask b){if(a.Width!=b.Width||a.Height!=b.Height)throw new ArgumentException("Mask dimensions differ");double best=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){long intersection=0,union=0;for(int y=0;y<a.Height;y++)for(int x=0;x<a.Width;x++){int av=255-a.Pixels[y*a.Width+x],bx=x+dx,by=y+dy,bv=bx>=0&&by>=0&&bx<b.Width&&by<b.Height?255-b.Pixels[by*b.Width+bx]:0;intersection+=Math.Min(av,bv);union+=Math.Max(av,bv);}if(union>0)best=Math.Max(best,(double)intersection/union);}return best;}
 }
}
